#include<bits/stdc++.h>

using namespace std;

int main(){
  int n;
  cin >> n;
  vector<int> a(n+1);
  for(int i=1;i<=n;i++){
    cin >> a[i];
  }

  vector<int> fl(n+1,0),s;
  int v=1; // any vertex is ok to start
  while(fl[v]==0){
    fl[v]=1;
    s.push_back(v);
    v=a[v];
  }

  vector<int> res;
  for(auto &nx : s){
    if(nx==v){v=-1;}
    if(v==-1){res.push_back(nx);}
  }
  cout << res.size() << "\n";
  for(int i=0;i<res.size();i++){
    if(i){cout << " ";}
    cout << res[i];
  }cout << "\n";
  return 0;
}

import java.util.*
fun main() {
	Scanner(System.`in`).use { sc ->
		val N = sc.nextInt()
		val A = IntArray(N + 1){if (it == 0) 0 else sc.nextInt()}
		var now = 1
		repeat(N) {now = A[now]}
		val B = mutableListOf<Int>()
		do {
			B.add(now)
			now = A[now]
		} while(B[0] != now)
		println(B.size)
		println(B.joinToString(" "))
	}
}

#include <atcoder/scc>
#include <iostream>
using namespace std;
int main() {
	int n;
	cin >> n;
	atcoder::scc_graph graph(++n);
	vector<int> a(n);
	for (int i = 1; i < n; ++i) {
		cin >> a[i];
		graph.add_edge(i, a[i]);
	}
	auto scc = graph.scc();
	for (auto &s : scc) {
		int now = s[0], len = s.size();
		if (len == 1) continue;
		cout << len << '\n';
		for (int i = 0; i < len; ++i) {
			cout << now << ' ';
			now = a[now];
		}
		return 0;
	}
}
